class Clocking {
  constructor(
    clockingId,
    ownerId,
    locationId,
    title,
    description,
    startTime,
    endTime,
    date
  ) {
    // string - generated by Firebase - not editable
    this.clockingId = clockingId; // '354adsf4rf4wfwe'

    // string - linked from Users database - not editable
    this.ownerId = ownerId;

    // string - linked from locations database - not editable
    this.locationId = locationId;

    // string - created based on input data - not editable
    this.title = title;

    // string - entered at creation - editable
    this.description = description;

    // Time - input from TimePicker - not editable once validated
    this.startTime = startTime;

    // Time - input from TimePicker - not editable once validated
    this.endTime = endTime;

    // Date - input from DatePicker - not editable once validated
    this.date = date;

    // boolean - set once the admin validates the entry - not editable
    this.isValidated = false;
  }
}

export default Clocking;
